from lib import *
S = SS('n25')
steps = [
    step("真实 HTTP 客户端看到的响应头:第一次写之前连续两次 c.Header(\"X-Step\", …),客户端只看到最后一次的值 2-before-again;c.String 之后再 c.Header(\"X-Late\", …) → 客户端看不到;WriteHeaderNow 之后再设 → 看不到;只 c.Status(202) 但还没写出时设的头 → 看得到(状态 202 + X-Late);c.Header(\"X-Gone\", \"\") 等于删除这个头。", t=tl(S(1)), mark=lidx(S(1), '/after-body', '/after-status'), done=lidx(S(1), '/before', '/status-only', '/delete'), b=bars([['写出之后设置的头(客户端能看到)', 0, '0 个'], ['写出之前设置的头(客户端能看到)', 1, '最后一次的值']], 1, mark=[0], done=[1]), kv=KV([['写出之前', '同一个键以最后一次为准'], ['写出之后', '客户端看不到'], ['c.Header(k, "")', '等于删除该头']], ['写出之后'])),
    step("Content-Type:不设时,第一次写正文由 Go 嗅探:HTML 被识别成 text/html; charset=utf-8,普通文本是 text/plain; charset=utf-8,JSON 字符串 {\"a\":1} 也只是 text/plain(不会识别成 application/json),PNG 魔数是 image/png;写之前设成 application/json 生效;写完正文之后再设,客户端看到的仍是嗅探的 text/html;c.String 总是 text/plain; charset=utf-8。", t=tl(S(2)), mark=lidx(S(2), '/sniff-json', '/set-after'), done=lidx(S(2), '/sniff-html', '/sniff-png', '/set-before', '/c-string'), kv=KV([['JSON 不设类型', 'text/plain,不是 application/json'], ['写后再设', '无效'], ['不确定时', '总是在写之前显式设置']], ['JSON 不设类型'])),
    step("Gin 这一层的 WriteHeader 只记录状态,重复调用不会碰 net/http:/gin-twice 里 WriteHeader(201)、WriteHeaderNow、WriteHeader(500)、WriteHeaderNow,客户端 201,服务器 ErrorLog 没有任何日志。绕过 Gin 在底层 ResponseWriter 上写两次:客户端仍是第一次的 201,但服务器 ErrorLog 出现两条 http: superfluous response.WriteHeader call,一条来自你的调用位置,另一条来自 gin.(*responseWriter).WriteHeaderNow——Gin 不知道你已经写过了,后面又替它写了一次。", t=tl(S(3)), mark=lidx(S(3), 'raw-twice', 'superfluous response.WriteHeader call from main.main.func2', 'WriteHeaderNow (response_writer.go:80)'), done=lidx(S(3), '/gin-twice'), kv=KV([['在 Gin 层写两次', '0 条日志,第一次生效'], ['绕过 Gin 写两次', '2 条 superfluous 日志'], ['客户端', '始终只看到第一次的状态']], ['绕过 Gin 写两次'])),
    step("想在正文之后再发的“头”:Trailer。写完正文后用 http.TrailerPrefix 作前缀设置(c.Header(\"Trailer:X-Body-Sha256\", …)):响应是 chunked 编码,读 body 之前 resp.Trailer 是空 map,读完 body 之后 resp.Trailer 里有 X-Body-Sha256=b4dc653fd8bab335;而普通的 X-Not-Trailer 同样设在写完之后,客户端没有收到。", t=tl(S(4)), mark=lidx(S(4), '读完 body 之后', 'X-Not-Trailer'), done=lidx(S(4), '读 body 之前'), kv=KV([['Trailer', '用 http.TrailerPrefix 前缀,写完正文后设'], ['传输', 'chunked,客户端读完 body 才能拿到'], ['普通头', '写完后设,客户端收不到']], ['Trailer'])),
]
A = mkartn('n25', 25, 'Gin,响应头,WriteHeader,Trailer,Content-Type,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 WriteHeader 之后再改 header:第一次写之前设的头(同一个键以最后一次为准)会发出,写出之后设的头客户端看不到;不设 Content-Type 时由 Go 在第一次写时嗅探,JSON 字符串被判成 text/plain;绕过 Gin 在底层写两次会触发 superfluous 日志;要在正文之后发的头只能用 Trailer。',
    '“我在 handler 最后加了个响应头,客户端怎么没收到?”这篇用真实的 HTTP 客户端把规则列清楚:什么时候设置才生效、不设 Content-Type 会被嗅探成什么、在 net/http 层重复 WriteHeader 会发生什么,以及真正需要在正文之后发送的信息该怎么办。',
    [('0 个', '写出之后设置的普通响应头,客户端能看到的个数'), ('text/plain', '不设 Content-Type 时 {"a":1} 被 Go 嗅探出的类型(不是 application/json)'), ('2 条', '绕过 Gin 在底层写两次 WriteHeader,服务器 ErrorLog 里的 superfluous 日志数(Gin 这层是 0 条)')],
    [('什么时候设置才生效', '<p>响应头要在状态行和第一段正文发出之前设置。之前设多次,以最后一次为准;<code>c.Header(key, "")</code> 等于删除。写出之后(<code>c.String</code> 之后、<code>WriteHeaderNow</code> 之后)再设,只是改了内存里的 map,客户端收不到。注意只调用了 <code>c.Status</code> 而没写正文时头还没发出,这时设置仍然有效——判断依据是 <code>c.Writer.Written()</code>。</p>'),
     ('Content-Type 的嗅探', '<p>没有显式设置 Content-Type 时,<code>net/http</code> 在第一次写时根据前 512 字节嗅探:HTML 是 <code>text/html</code>,PNG 是 <code>image/png</code>,JSON 文本只是 <code>text/plain</code>。写完之后再设已经来不及。用 <code>c.JSON</code> / <code>c.String</code> 这些方法时 Gin 已经替你设好了,只有直接写 <code>c.Writer</code> 时才需要注意。</p>'),
     ('重复 WriteHeader', '<p>Gin 自己的 <code>WriteHeader</code> 只是记录状态,所以在 Gin 层写多次既安全又没有日志,第一次发出的状态生效。如果拿到底层 <code>http.ResponseWriter</code> 直接写,标准库会把 <code>http: superfluous response.WriteHeader call</code> 记到服务器的 <code>ErrorLog</code> 里;而且因为 Gin 不知道你已经写过,请求结束时它又替你写了一次,所以会有两条日志。</p>'),
     ('Trailer', '<p>真要在正文之后附带信息(比如边写边算的校验和),HTTP 的办法是 trailer:在写完正文之后用 <code>http.TrailerPrefix</code> 作为前缀设置头,服务器会用 chunked 编码把它们放在最后,客户端要读完 body 才能从 <code>resp.Trailer</code> 取到。很多客户端和中间件不处理 trailer,本文只验证了 Go 的客户端。</p>')],
    steps,
    [ENV_N_GIN + '。全部用真实的 httptest.NewServer 与 Go 的 http.Client;第三节给服务器配置了自己的 ErrorLog 来接收日志;每种情形各一次',
     '没有验证:浏览器、curl、反向代理对 trailer 的处理;HTTP/2 下“写出之后设头”的行为;100/103 等 1xx 响应的发送;Content-Length 与 chunked 的选择规则;在 gzip 中间件之后嗅探的行为'],
    '写出之后改头')
